rush-control{display:flex;align-items:center;gap:9px;margin:9px 4px 0;color:#8e9a8d;font:9px 'DM Mono';letter-spacing:.5px}.brush-label{font-size:8px;letter-spacing:1px}.brush-control input{width:85px;height:3px;accent-color:#77975d}.brush-control span:last-child{color:#586d55}.right-panel{border-left:1px solid var(--line);padding:26px 21px 14px;background:#fdfefb;display:flex;flex-direction:column;min-width:0}.panel-top,.section-heading{display:flex;justify-content:space-between;align-items:center}.panel-top .eyebrow{font-size:9px}.more-btn{border:0;background:none;color:#9aa59a;letter-spacing:2px;font-weight:bold}.population-head{display:flex;justify-content:space-between;align-items:center;margin:22px 0 10px}.stat-label{font:9px 'DM Mono';letter-spacing:.9px;color:#9aa399}.population-number{font:600 29px 'Space Grotesk';letter-spacing:-1px;color:#213223;margin-top:3px}.population-number small{font:400 11px 'DM Sans';letter-spacing:0;color:#9aa39a}.pop-orb{width:43px;height:43px;background:#eaf1e4;color:#799867;border-radius:50%;display:grid;place-items:center;font-size:21px}.pop-meter{height:4px;background:#edf0e9;border-radius:5px;overflow:hidden}.pop-meter span{display:block;height:100%;width:0;background:linear-gradient(90deg,#74935e,#bed27f);border-radius:5px;transition:width .3s}.stat-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:15px}.stat-card{padding:11px 10px 9px;border:1px solid #e9ede6;border-radius:5px;background:#fff}.stat-card>b{display:block;font:600 21px 'Space Grotesk';margin:4px 0 2px;color:#26382a}.stat-card small{font-size:9px;color:#9ba49a}.status-dot{display:inline-block;width:5px;height:5px;border-radius:50%;margin-right:3px}.status-dot.green{background:#80a66e}.status-dot.gold{background:#d3ac64}.panel-divider{height:1px;background:#e9ede7;margin:17px 0 15px}.section-heading{font:500 9px 'DM Mono';letter-spacing:1.05px;color:#718071}.text-action{border:0;background:none;color:#92a18b;font:8px 'DM Mono';letter-spacing:.4px}.kingdom-list{margin-top:11px;display:flex;flex-direction:column;gap:8px}.kingdom-item{display:flex;align-items:center;gap:9px;padding:8px 7px;border-radius:4px;background:white;border:1px solid #edf0ea}.kingdom-swatch{width:8px;height:26px;border-radius:4px}.kingdom-info{flex:1;min-width:0}.kingdom-info b{display:block;font:600 11px 'Space Grotesk';color:#344436;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.kingdom-info small{color:#9ba49a;font-size:9px}.kingdom-size{font:10px 'DM Mono';color:#7b887b}.empty-state{text-align:center;padding:18px 7px 14px;color:#9da79b}.empty-state>span{display:block;color:#b7c8a9;font-size:20px;margin-bottom:7px}.empty-state b{display:block;font:500 11px 'Space Grotesk';color:#667464}.empty-state small{display:block;font-size:9px;line-height:1.5;margin:5px auto 0;max-width:180px}.live-label{font:8px 'DM Mono';letter-spacing:.5px;color:#7f9d6f}.live-label i{display:inline-block;width:5px;height:5px;background:#89aa72;border-radius:50%;margin-right:3px}.eco-row{display:flex;align-items:center;gap:9px;margin-top:11px;color:#718071;font-size:10px}.eco-icon{width:21px;height:21px;border-radius:5px;display:grid;place-items:center;background:#edf3e9;color:#68905d;font-size:13px}.eco-icon.food{background:#f6f0df;color:#c39b4c}.eco-icon.fire{background:#f8e9e3;color:#ce775a}.eco-row>b{margin-left:auto;font:500 11px 'DM Mono';color:#526352}.eco-trend{color:#7ea46c;font-size:11px}.eco-trend.muted{color:#b5bcb3}.events-divider{margin-top:16px}.event-count{font:9px 'DM Mono';color:#afb6ad}.event-list{margin-top:8px;max-height:160px;overflow:auto}.event-item{display:grid;grid-template-columns:31px 1fr;gap:8px;padding:8px 0;border-bottom:1px solid #f0f2ed}.event-time{font:8px 'DM Mono';color:#a3ada1;padding-top:2px}.event-copy{font-size:9px;line-height:1.45;color:#778277}.event-copy b{font-weight:600;color:#485749}.event-icon{display:inline-block;margin-right:4px;color:#8da96d}.panel-bottom{margin-top:auto;padding-top:15px;color:#a0a99f;font-size:9px;border-top:1px solid #edf0eb}.sparkle{color:#a7bd79;margin-right:4px}.bottomline{height:34px;border-top:1px solid #e8ece5;display:flex;justify-content:space-between;align-items:center;padding:0 20px;color:#a2aaa0;font:8px 'DM Mono';letter-spacing:.5px}.bottomline b{font-weight:400;color:#718071}.bottomline i{font-style:normal;color:#a3bd75;margin-left:5px}.modal-backdrop{position:fixed;inset:0;background:#111b14a8;display:none;align-items:center;justify-content:center;z-index:20;padding:20px}.modal-backdrop.open{display:flex}.modal{position:relative;background:#fcfdf8;border:1px solid #e0e8d8;border-radius:9px;padding:35px 38px;width:min(460px,100%);box-shadow:0 25px 90px #0e1a1170}.modal-close{position:absolute;right:15px;top:12px;border:0;background:none;color:#8c998b;font-size:23px}.modal-mark{color:#9eb86c;font-size:27px;margin-bottom:13px}.modal h2{font:600 27px 'Space Grotesk';letter-spacing:-.7px;margin:8px 0 10px}.modal p{font-size:12px;line-height:1.65;color:#7c887c}.help-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:20px 0 23px}.help-grid div{display:flex;align-items:center;gap:8px;font-size:10px;color:#667365}.help-grid kbd{padding:4px 6px;border:1px solid #e2e8dd;background:#f6f8f2;border-radius:3px;color:#64825c;font:8px 'DM Mono';white-space:nowrap}.primary-btn{width:100%;border:0;border-radius:4px;background:#385d3c;color:#f6f7ed;padding:12px;font:500 10px 'DM Mono';letter-spacing:.8px}.primary-btn span{float:right;font-size:14px;margin-top:-3px;color:#cfdfa3}
@media(max-width:1150px){.world-layout{grid-template-columns:65px minmax(460px,1fr) 260px}.left-rail{padding:24px 8px}.rail-label{display:none}.rail-btn{justify-content:center;padding:10px 4px}.rail-btn i{display:none}.mini-map-wrap{padding:9px 1px}.mini-title{font-size:7px;padding-left:1px}.mini-caption{font-size:7px}.right-panel{padding:24px 15px}.game-area{padding-left:19px;padding-right:19px}.tool-btn{min-width:46px}.tool-btn kbd{display:none}}
@media(max-width:900px){.world-layout{grid-template-columns:58px minmax(0,1fr)}.right-panel{display:none}.game-area{padding:22px 20px}.canvas-wrap{height:clamp(390px,58vh,600px)}.world-title{display:none}}
@media(max-width:600px){.topbar{height:55px;padding:0 14px}.edition,.brand-divider{display:none}.brand{font-size:13px}.top-actions{gap:6px}.icon-btn{width:28px;height:28px}.save-btn{padding:8px 9px;font-size:9px}.world-layout{display:block;min-height:calc(100vh - 84px)}.left-rail{display:none}.game-area{padding:18px 11px 12px}.world-heading{align-items:center;margin-bottom:12px}h1{font-size:21px}.eyebrow{font-size:8px}.world-controls{gap:5px}.time-control{height:30px;padding:0 3px;gap:0}.time-label{display:none}.time-control .time-divider{margin:0 3px}.time-control button{padding:5px 5px}.round-btn{height:30px;width:30px}.canvas-wrap{height:52vh;min-height:350px;max-height:520px}.map-legend{top:auto;bottom:13px;left:12px;right:auto;padding:7px}.map-zoom{right:10px;bottom:10px}.intro-tip{max-width:calc(100% - 30px);white-space:normal;width:max-content}.intro-tip small{max-width:205px}.godbar{margin-top:11px;padding:10px 7px 8px}.tool-heading{margin-left:5px}.tool-list{gap:1px;overflow-x:auto;padding-bottom:2px}.tool-btn{min-width:48px;padding:7px 2px 5px;font-size:8px}.tool-icon{width:27px;height:26px}.tool-separator{margin:0 2px;height:34px}.brush-control{margin-top:7px}.bottomline{height:29px;padding:0 11px;font-size:7px}.bottomline span:nth-child(2){display:none}.map-footer{padding:0 8px;font-size:8px}.map-footer-right{gap:8px;font-size:7px}.toast{font-size:10px;bottom:52px}}
@media(max-height:730px) and (min-width:901px){.canvas-wrap{height:44vh;min-height:330px}.game-area{padding-top:18px}.world-heading{margin-bottom:11px}.godbar{margin-top:11px}.right-panel{padding-top:19px}.population-head{margin:15px 0 8px}.panel-divider{margin:13px 0 11px}.event-list{max-height:115px}}

(() => {
  'use strict';
  const canvas = document.getElementById('world'), ctx = canvas.getContext('2d');
  const mini = document.getElementById('minimap'), mctx = mini.getContext('2d');
  const COLS = 72, ROWS = 48, TYPES = ['deep','shallow','sand','grass','forest','mountain'];
  const colors = { deep:'#436c78', shallow:'#61928d', sand:'#d9c890', grass:'#8eae72', forest:'#557f58', mountain:'#84918a' };
  let seed = 82426;
  const rand = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };
  const hash = (x,y) => { let n = (x*374761393+y*668265263+seed*982451653)|0; n=(n^(n>>>13))*1274126177; return ((n^(n>>>16))>>>0)/4294967295; };
  let grid = [], agents = [], kingdoms = [], fires = [], effects = [], events = [];
  let nextAgent = 1, nextKingdom = 1, day = 1, tick = 0, speed = 1, paused = false, activeTool = 'inspect', brush = 2;
  let canvasW=800,canvasH=500,dpr=1,scale=10,panX=0,panY=0, zoom=1, pointer={x:0,y:0,valid:false}, drawing=false, panning=false, lastBrushCell='', lastTick=0, toastTimer;
  const seasons=['Primavera','Verano','Otoño','Invierno'];
  const toolNames={inspect:'Mirar',raise:'Elevar terreno',lower:'Hundir terreno',forest:'Bosque plantado',water:'Agua nueva',villager:'Aldeano invocado',lightning:'Rayo divino',bomb:'Explosión',acid:'Lluvia ácida'};
  const at=(x,y)=>x>=0&&y>=0&&x<COLS&&y<ROWS?grid[y][x]:null;
  const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  function makeCell(x,y){
    const nx=(x-COLS/2)/(COLS*.48), ny=(y-ROWS/2)/(ROWS*.49), r=Math.sqrt(nx*nx+ny*ny);
    const wave=Math.sin(x*.31+y*.14)*.045+Math.cos(y*.28-x*.11)*.035+(hash(x,y)-.5)*.11;
    const h=1-r+wave;
    let type=h<.04?'deep':h<.12?'shallow':h<.18?'sand':h>.68?'mountain':h>.43&&hash(x+71,y+19)>.29?'forest':'grass';
    if(type==='deep'&&h>.015)type='shallow';
    const elevation=type==='mountain'?2:type==='forest'||type==='grass'?1:0;
    return {type,elevation,tree:type==='forest'&&hash(x+80,y+90)>.17,food:hash(x+22,y+3)>.91?1:0,wood:0,stone:0,owner:0,burning:0,acid:0,house:null,texture:hash(x+seed,y-seed)};
  }
  function generateWorld(){
    seed=82426;grid=Array.from({length:ROWS},(_,y)=>Array.from({length:COLS},(_,x)=>makeCell(x,y)));
    // Broad, navigable landmasses with coves and a small eastern islet.
    for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++){
      const nx=(x-COLS*.5)/(COLS*.47),ny=(y-ROWS*.5)/(ROWS*.48),r=Math.sqrt(nx*nx+ny*ny);
      if(x>COLS*.76&&y>ROWS*.48&&y<ROWS*.78&&Math.hypot((x-COLS*.83)/7,(y-ROWS*.64)/5)<1.02){grid[y][x].type=hash(x,y)>.82?'forest':'grass';grid[y][x].tree=hash(x+51,y)>.53;grid[y][x].elevation=1;continue;}
      if(r>.96&&grid[y][x].type!=='deep')grid[y][x].type='shallow';
      if(r>1.015)grid[y][x].type='deep';
    }
    agents=[];kingdoms=[];fires=[];effects=[];events=[];nextAgent=nextKingdom=1;day=1;tick=0;
    panX=panY=0;zoom=1;updateWorldStats();render();
  }
  function resize(){
    const rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;
    dpr=Math.min(window.devicePixelRatio||1,2);canvasW=rect.width;canvasH=rect.height;
    canvas.width=Math.round(canvasW*dpr);canvas.height=Math.round(canvasH*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);
    scale=Math.min(canvasW/COLS,canvasH/ROWS)*.96*zoom;render();
  }
  function screenOrigin(){return {x:(canvasW-COLS*scale)/2+panX,y:(canvasH-ROWS*scale)/2+panY};}
  function toCell(px,py){const o=screenOrigin();return {x:Math.floor((px-o.x)/scale),y:Math.floor((py-o.y)/scale)};}
  function notify(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1650);}
  function addEvent(icon, message, dayLabel=`AÑO ${Math.floor((day-1)/360)+1} · DÍA ${((day-1)%360)+1}`){events.unshift({icon,message,time:dayLabel});events=events.slice(0,5);renderEvents();}
  function renderEvents(){document.getElementById('eventCount').textContent=String(events.length).padStart(2,'0');document.getElementById('eventList').innerHTML=events.map(e=>`<div class="event-item"><span class="event-time">${e.time}</span><div class="event-copy"><span class="event-icon">${e.icon}</span>${e.message}</div></div>`).join('')||'<div class="empty-state"><small>Los acontecimientos aparecerán aquí.</small></div>';}
  function updateWorldStats(){
    const land=grid.flat().filter(c=>c.type!=='deep'&&c.type!=='shallow').length;
    document.getElementById('landPercent').textContent=`${Math.round(land/(COLS*ROWS)*100)}%`;
    document.getElementById('population').innerHTML=`${agents.length} <small>almas</small>`;
    document.getElementById('kingdomCount').textContent=kingdoms.length;
    document.getElementById('villageCount').textContent=kingdoms.reduce((n,k)=>n+k.villages,0);
    document.getElementById('treeCount').textContent=grid.flat().filter(c=>c.tree).length;
    document.getElementById('foodCount').textContent=grid.flat().reduce((n,c)=>n+c.food,0);
